/**
 * The model-driven `prune` tool (named to avoid clashing with the platform's
 * default compress/compact tooling). Registered as a DIRECT tool
 * (`codemode: false`) so its full PRUNE_RANGE description ships with every
 * request: core tool.ts only advertises `codemode === false` tools in direct
 * tool definitions, while `codemode: true` (the platform default) routes the
 * tool into the Code Mode `execute` catalog whose descriptions are truncated
 * to 120 chars - hiding the BOUNDARY IDS rules the model needs. The model
 * picks conversation ranges using injected boundary IDs (`mNNNN` / `bN`) and
 * writes the summaries; this tool validates the selection, folds in any
 * compression blocks the range consumes, records the resulting state, and
 * persists it. Future context transforms then swap the covered ranges for
 * the synthetic summaries on every dispatch.
 */

export const PRUNE_TOOL_NAME = "prune";

/**
 * The subset of `ToolEditor` (`@opencode/plugin` promise API) the registration
 * path touches. `add` and `list` are both optional so a runtime predating
 * either still registers: a missing `add` is reported, a missing `list` only
 * means the tool is registered without its presence ever being confirmed.
 */
export interface PruneToolEditor {
  readonly add?: (definition: unknown) => void;
  readonly list?: () => readonly unknown[];
}

export type PruneToolRegistration =
  /** `add` ran and `prune` is present in the editor's own registry listing. */
  | { readonly ok: true }
  /** `add` is absent, or the registry refused the definition and dropped it. */
  | { readonly ok: false; readonly reason: string };

/**
 * True when `prune` appears in a tool listing — `ToolEditor.list()` (the draft
 * the transform writes into) or `ToolDomain.list()` (the committed registry).
 *
 * Entries are matched on the raw `name` and on the registry's `id` (core's
 * `effectiveName`: the name run through `normalizedName`, prefixed with the
 * namespace when `options.namespace` is set), so the check holds whichever key
 * a runtime stamps. A listing that is not an array counts as "absent": the
 * caller treats absence as a registration failure, and a malformed listing is
 * not evidence the tool is reachable.
 */
export function pruneToolRegistered(tools: unknown): boolean {
  if (!Array.isArray(tools)) return false;
  return tools.some((entry) => {
    if (typeof entry !== "object" || entry === null) return false;
    const { name, id } = entry as { name?: unknown; id?: unknown };
    return name === PRUNE_TOOL_NAME || id === PRUNE_TOOL_NAME;
  });
}

/**
 * Registers the `prune` definition and reports whether the registry kept it.
 *
 * Core's editor `add` DROPS a definition that fails `registrationError` -
 * invalid name, the reserved `execute` id, or a schema `ToolDefinition.make`
 * rejects - recording a `RegistrationError` and returning without inserting
 * (packages/core/src/tool.ts:177-185). The only other trace is an
 * `Effect.logError` in the domain's `notify`
 * (packages/core/src/tool.ts:206-218), which never reaches the plugin. So a
 * rejected registration used to be invisible from here while the DCP system
 * prompt kept advertising `prune`, and every call failed with core's generic
 * 'No tool named "prune" is currently available'.
 *
 * `editor.list()` reads the same draft map `add` writes, so the check is a
 * local array read — no I/O, safe to run on every transform pass (registration
 * and reloads, never a dispatch).
 */
export function addPruneTool(
  editor: PruneToolEditor,
  definition: ReturnType<typeof pruneToolDefinition>,
): PruneToolRegistration {
  if (typeof editor.add !== "function") {
    return {
      ok: false,
      reason:
        "the tool editor exposes no `add()`; the `prune` tool was never registered while the system prompt still advertises it",
    };
  }
  editor.add(definition);
  if (typeof editor.list !== "function") return { ok: true };
  if (pruneToolRegistered(editor.list())) return { ok: true };
  return {
    ok: false,
    reason:
      "the runtime rejected the `prune` definition and dropped it from the tool registry (invalid name, reserved `execute` id, or an unusable input schema); the system prompt still advertises a tool that can never be called",
  };
}

/**
 * The zero-gain floor (`ZERO_GAIN_MIN_TOKENS`,
 * `ZERO_GAIN_STANDING_SUMMARY_FRACTION`) is declared in `lib/constants.ts` so
 * the enforcement here and the sentence describing it in `PRUNE_RANGE`
 * (`lib/prompts.ts`) read one number. Re-exported for the existing importers.
 */
export { ZERO_GAIN_MIN_TOKENS, ZERO_GAIN_STANDING_SUMMARY_FRACTION };

export interface PruneRangeEntry {
  startId: string;
  endId: string;
  summary: string;
}

export interface PruneToolArgs {
  topic: string;
  content: PruneRangeEntry[];
}

const INPUT_SCHEMA = {
  type: "object",
  properties: {
    topic: {
      type: "string",
      description: "Short label (3-5 words) for display - e.g., 'Auth System Exploration'",
    },
    content: {
      type: "array",
      description: "One or more ranges to prune, each with start/end boundaries and a summary",
      items: {
        type: "object",
        properties: {
          startId: {
            type: "string",
            description: "Message or block ID marking the beginning of range (e.g. m0001, b2)",
          },
          endId: {
            type: "string",
            description: "Message or block ID marking the end of range (e.g. m0012, b5)",
          },
          summary: {
            type: "string",
            description: "Complete technical summary replacing all content in range",
          },
        },
        required: ["startId", "endId", "summary"],
        additionalProperties: false,
      },
    },
  },
  required: ["topic", "content"],
  additionalProperties: false,
} as const;

export interface PruneDeps {
  store: StateStore;
  mirror: TranscriptMirror;
  logger: Logger;
  config: DcpOptions;
  getModelContextLimit: (sessionId: string) => number | undefined;
  getUsageTokens: (sessionId: string) => number;
  /**
   * Marks the usage estimate as predating this prune. The next dispatch then
   * floors its own transcript measurement with the prune's recorded
   * post-prune estimate instead of maxing the pre-prune provider delta back in
   * (which re-nudged the model with the number it just acted on). Optional so
   * embedders without a tracker keep working.
   */
  markPruned?(sessionId: string): void;
  /** Publishes a completed compression to the TUI stats bridge (optional). */
  recordCompression?(input: { sessionId: string; record: CompressionEventRecord }): void;
}

export interface PruneToolContext {
  sessionID: string;
  progress?: (update: Record<string, unknown>) => Promise<void>;
}

interface ResolvedPlan {
  entry: PruneRangeEntry;
  coveredKeys: string[];
  coveredToolIds: string[];
  coveredTokens: number;
  anchorKey: string;
  /** Active blocks fully consumed by this range (summaries fold into the new one). */
  consumedBlockIds: number[];
}

// Tool transforms can recreate definitions; calls sharing a store must still share the queue.
const pruneQueues = new WeakMap<StateStore, Map<string, Promise<void>>>();

export function pruneToolDefinition(deps: PruneDeps) {
  let queue = pruneQueues.get(deps.store);
  if (!queue) pruneQueues.set(deps.store, (queue = new Map()));
  const pending = queue;
  return {
    name: PRUNE_TOOL_NAME,
    description: PRUNE_RANGE,
    input: INPUT_SCHEMA,
    // Direct registration: core tool.ts advertises `codemode === false` tools
    // as native tool definitions (full description ships every request), while
    // `codemode: true`/unset hides the tool inside the Code Mode `execute`
    // catalog, whose descriptions are truncated to 120 chars - too short for
    // the PRUNE_RANGE boundary rules every piece of DCP model copy tells the
    // model to follow. The split is `codemode === false` vs `!== false`, not
    // "explicit true", so leaving it unset is as bad as setting it true
    // (packages/core/src/tool.ts:234-235; the definitions list at :257-261).
    // The permission is pinned to the tool's own name (core's whollyDisabled
    // falls back to `tool.options?.permission ?? name`, packages/core/src/
    // tool.ts:231), so the action stays stable regardless of the platform
    // default; permission actions are free-form strings matched by wildcard,
    // so "prune" is a valid action and needs no registration of its own.
    //
    // This satisfies `Tool.Options` (packages/schema/src/tool.ts:32-42): the
    // `codemode: boolean` arm, which forbids `pinned`. `prune` is not
    // reserved - `registrationError` reserves only the `execute` id, and only
    // for `codemode === false` registrations (packages/core/src/tool.ts:
    // 311-314). `name` also passes the `/^[A-Za-z0-9_-]+$/` check on the same
    // path, which is what `addPruneTool`'s post-add verification proves.
    options: { codemode: false, permission: PRUNE_TOOL_NAME },
    execute: async (input: unknown, context: PruneToolContext) => {
      // Expected failures are THROWN, never returned as model-visible success
      // content. Log here: rejected Promise executions can bypass the host's
      // `execute.after` hook. A returned `context error: …` string is an ordinary COMPLETED
      // tool result that the model can only disambiguate by parsing an English
      // prefix - so it retried the same broken call. This catch only logs and
      // RETHROWS: it must never turn an expected failure into a result.
      const sessionId = context.sessionID;
      const run = (pending.get(sessionId) ?? Promise.resolve()).then(() =>
        runPrune(deps, input, context),
      );
      const tail = run.then(() => {}, () => {});
      pending.set(sessionId, tail);
      try {
        return await run;
      } catch (error) {
        deps.logger.warn("prune tool failed", {
          sessionID: context.sessionID,
          error: error instanceof Error ? error.message : String(error),
        });
        throw error;
      } finally {
        if (pending.get(sessionId) === tail) pending.delete(sessionId);
      }
    },
  };
}

/**
 * One atomic multi-range prune: validate -> resolve -> expand placeholders ->
 * zero-gain guard -> apply -> persist. There is deliberately no `catch` in
 * here: every failure mode below (unknown/invalid boundary ID, inverted or
 * overlapping range, unknown `(bN)` placeholder, zero-gain re-summarize) is an
 * EXPECTED failure and must reach the runner as a throw, so the platform marks
 * the call as failed instead of returning prose the model reads as success.
 *
 * Atomicity comes from ordering, not from the catch: `expandPlaceholders` and
 * the zero-gain guard both run over ALL plans before the first
 * `applyCompression`, so a bad second entry cannot leave the first one
 * half-applied.
 */
async function runPrune(deps: PruneDeps, input: unknown, context: PruneToolContext) {
  const args = validateArgs(input);
  const sessionId = context.sessionID;

  const index = deps.mirror.get(sessionId);
  if (!index || index.messages.length === 0) {
    throw new Error("no conversation context is available yet. Send a message first.");
  }

  const runtime = await deps.store.ensure(sessionId);

  // Rewrite legacy `tool#N` keys in persisted active blocks to current scan
  // keys so boundary resolution / whole-block consumption see consistent
  // coverage after an upgrade. Idempotent; no-op once normalized.
  normalizeLegacyBlockKeys(runtime.state, index.keys, index.messages);

  // Expected, recoverable failures (unknown IDs, overlapping ranges, invalid
  // boundaries). They propagate out of `runPrune` and the platform marks the
  // call as a real tool failure, so the model retries with corrected ids
  // instead of parsing prose out of a "successful" result.
  const plans = resolvePlans(args, index, runtime);

  await context.progress?.({ title: `DCP: pruning "${args.topic}"` });

  let totalNewMessages = 0;
  let toolsCovered = 0;
  let tokensCovered = 0;
  let tokensSummaries = 0;
  let lastBlockId = 0;
  const blockLabels: string[] = [];

  // Expand every summary up front: a bad `(bN)` reference in a model-written
  // summary (expandPlaceholders) must abort the whole call BEFORE the first
  // block is recorded - multi-range prunes should be atomic, not partially
  // applied. Nothing downstream of this map has touched state yet, so the
  // throw that aborts a bad entry also aborts the whole call; the platform
  // frames it as a failed tool call and the model retries with a corrected
  // summary. Interruption handling is left entirely to the platform.
  const expandedSummaries = plans.map((plan) =>
    expandPlaceholders(plan.entry.summary, runtime.state),
  );

  // Zero-gain re-prune guard. A range whose coverage is exactly the blocks
  // it consumes re-summarizes content that is ALREADY out of the outbound
  // transcript (the consumed block's standing summary replaced those
  // originals long ago), so the only tokens such a pass can free are the
  // delta between the old and the new summary - historically ~0 (196 -> 179
  // token swaps), while the record claimed the full original coverage as
  // "saved" and the usage note kept saying "still above - prune again",
  // driving the model to re-prune the same region every few seconds.
  // Reject BEFORE any state mutation. A fold clears the guard only when it
  // frees at least max(ZERO_GAIN_MIN_TOKENS, half of the standing summary),
  // except placeholder-free drops may free less than the absolute floor.
  // Any range covering new messages skips the guard entirely. The
  // throw (not a returned result) is what stops the retry loop - the platform
  // reports the call as failed.
  const zeroGainRanges: string[] = [];
  for (let planIndex = 0; planIndex < plans.length; planIndex++) {
    const plan = plans[planIndex]!;
    let consumedCoverage = 0;
    let consumedSummaryTokens = 0;
    let consumedOriginalTokens = 0;
    for (const id of plan.consumedBlockIds) {
      const consumed = runtime.state.blocks[String(id)];
      consumedCoverage += consumed?.coveredKeys.length ?? 0;
      consumedSummaryTokens += Math.max(0, consumed?.summaryTokens ?? 0);
      consumedOriginalTokens += Math.max(0, consumed?.compressedTokens ?? 0);
    }
    if (Math.max(0, plan.coveredKeys.length - consumedCoverage) > 0) continue;
    // Preview of the summaryTokens applyCompression would record for this
    // plan (wrapper included; the provisional block id only varies in a
    // character or two of the wrapper, but match the allocator anyway).
    const newSummaryTokens = countTokens(
      wrapCompressedSummary(runtime.state.nextBlockId + planIndex, expandedSummaries[planIndex]!),
    );
    const freshOriginalTokens = Math.max(0, plan.coveredTokens - consumedOriginalTokens);
    const reclaim = freshOriginalTokens + consumedSummaryTokens - newSummaryTokens;
    // Placeholder-free drops may clear small dead blocks, but must still be substantially shorter.
    const dropsContent =
      plan.consumedBlockIds.length > 0 &&
      plan.entry.summary.match(BLOCK_PLACEHOLDER_REGEX) === null && reclaim > 0;
    const floor = Math.max(
      dropsContent ? 1 : ZERO_GAIN_MIN_TOKENS,
      Math.ceil(consumedSummaryTokens * ZERO_GAIN_STANDING_SUMMARY_FRACTION),
    );
    if (reclaim < floor) {
      const blocks = plan.consumedBlockIds.map((id) => formatBlockRef(id)).join(", ");
      zeroGainRanges.push(
        `${plan.entry.startId}..${plan.entry.endId}${blocks ? ` (already compressed as ${blocks}, standing summary ${consumedSummaryTokens} tokens)` : ""} frees ${Math.max(0, reclaim)} of the ${floor}-token minimum`,
      );
    }
  }
  if (zeroGainRanges.length > 0) {
    throw new Error(
      `these ranges add no messages outside active compressed sections and would free too few tokens: ${zeroGainRanges.join("; ")}. Prune messages not yet inside a compressed section, or fold a block only when the replacement summary is at most half the standing summary and frees at least ${ZERO_GAIN_MIN_TOKENS} tokens. Placeholder-free drops may free less than ${ZERO_GAIN_MIN_TOKENS} tokens but must still halve the standing summary and save tokens - a re-summarize of the same size is a no-op that costs a whole model turn.`,
    );
  }

  // Invalid prunes must not change automatic pruning state or the prompt-cache prefix.
  deduplicate(runtime.state, index, deps.config);
  purgeErrors(runtime.state, index, deps.config);

  for (let planIndex = 0; planIndex < plans.length; planIndex++) {
    const plan = plans[planIndex]!;
    const block = applyCompression({
      state: runtime.state,
      refs: runtime.refs,
      topic: args.topic,
      summary: expandedSummaries[planIndex]!,
      coveredKeys: plan.coveredKeys,
      coveredToolIds: plan.coveredToolIds,
      coveredTokens: plan.coveredTokens,
      consumedBlockIds: plan.consumedBlockIds,
      anchorKey: plan.anchorKey,
    });
    const consumedCoverage = plan.consumedBlockIds.reduce(
      (sum, id) => sum + (runtime.state.blocks[String(id)]?.coveredKeys.length ?? 0),
      0,
    );
    totalNewMessages += Math.max(0, plan.coveredKeys.length - consumedCoverage);
    toolsCovered += plan.coveredToolIds.length;
    tokensCovered += Math.max(0, plan.coveredTokens);
    tokensSummaries += Math.max(0, block.summaryTokens);
    lastBlockId = block.blockId;
    blockLabels.push(formatBlockRef(block.blockId));
  }

  // Honest outbound accounting, computed while the sums are exact: tokens
  // whose original text is inside a consumed block are NOT in the
  // transcript anymore (the block's standing summary is), so "before" is
  // the still-fresh original content plus the summaries being replaced -
  // never the full covered-original estimate. The old before/after pair
  // made a zero-gain re-prune report the entire original coverage as
  // saved for swapping a ~196-token summary for a ~179-token one.
  const consumedSummaryTokens = sumConsumedBlocks(plans, runtime, "summaryTokens");
  const consumedOriginalTokens = sumConsumedBlocks(plans, runtime, "compressedTokens");
  const tokensBefore =
    Math.max(0, tokensCovered - consumedOriginalTokens) + consumedSummaryTokens;
  const tokensSaved = Math.max(0, tokensBefore - tokensSummaries);

  // Capture occupancy BEFORE `markPruned`: the tracker zeroes its estimate
  // and drops the baseline on a prune (the on-hand delta describes the
  // pre-prune prompt), so reading it afterwards would report 0. That also
  // makes a SECOND prune in the same turn read 0 - the previous record's
  // `usageAfter` is then the post-prune base to subtract this pass from.
  const usageTokens = deps.getUsageTokens(sessionId);
  const previousUsage =
    usageTokens > 0 ? usageTokens : (runtime.state.stats.recentCompressions.at(-1)?.usageAfter ?? 0);
  // `tokensSaved` is the honest outbound delta computed above: exactly the
  // fresh originals plus consumed summaries this pass removed, minus the
  // new summaries standing in for them.
  const postPruneUsage = Math.max(0, previousUsage - tokensSaved);

  const record: CompressionEventRecord = {
    at: Date.now(),
    blockId: lastBlockId,
    topic: args.topic,
    ranges: plans.length,
    messagesCovered: totalNewMessages,
    toolsCovered,
    tokensBefore,
    tokensAfter: tokensSummaries,
    tokensSaved,
    // Persisted with the record so the ack on the next dispatch repeats the
    // figure the usage note prints instead of re-measuring the wire transcript
    // alone (which omits the system prompt and tool definitions and read ~3K
    // against this note's ~20K for the same prune).
    usageAfter: postPruneUsage > 0 ? postPruneUsage : undefined,
  };

  // The record rides in the persisted state (not just the TUI bridge's
  // in-memory snapshot, which resets with every plugin generation) so the
  // compression history survives plugin reloads and server restarts.
  runtime.state.stats.recentCompressions.push(record);
  while (runtime.state.stats.recentCompressions.length > MAX_RECENT_COMPRESSIONS) {
    runtime.state.stats.recentCompressions.shift();
  }

  // Any occupancy recorded before this point describes the pre-prune
  // prompt; flag it so the next dispatch measures fresh instead of
  // re-nudging with the number the model just acted on.
  deps.markPruned?.(sessionId);

  await deps.store.persist(sessionId);

  try {
    deps.recordCompression?.({ sessionId, record });
  } catch {
    // Display-only bridge.
  }
  deps.logger.debug("compression applied", {
    sessionId,
    topic: args.topic,
    blocks: blockLabels,
    activeBlocks: activeBlocks(runtime.state).length,
    totalPrunedTokens: runtime.state.stats.totalPrunedTokens,
  });

  // The window always resolves (unlisted model -> default), so the note
  // names BOTH denominators exactly like the pressure reminder does: a
  // percentage of only one of them is what reads as stale or contradictory.
  const window = deps.getModelContextLimit(sessionId) ?? FALLBACK_CONTEXT_WINDOW;
  const budget = resolveLimit(deps.config.maxContextLimit, window);
  // Same spellings as the pressure reminder (`contextUsage` / `budgetClause`),
  // so this result can never contradict the nudge the model just acted on -
  // naming the window first and the budget as a trailing threshold.
  const usageNote =
    postPruneUsage > 0 && budget > 0
      ? ` Context is now ${contextUsage(postPruneUsage, window)}${budgetClause(postPruneUsage, budget)}. ${
          postPruneUsage < budget
            ? "No further pruning needed - continue with the current task."
            : "Prune again only if another meaningfully sized closed section has appeared outside the active compressed sections; otherwise continue working."
        }`
      : "";

  const outcome =
    totalNewMessages > 0
      ? `Pruned ${totalNewMessages} message(s) into ${blockLabels.length} pruned section(s) (${blockLabels.join(", ")}).`
      : `Re-summarized already-compressed content into ${blockLabels.length} pruned section(s) (${blockLabels.join(", ")}), freeing ~${tokenLabel(tokensSaved)} tokens of standing summary. No new messages were covered - do not repeat this pass.`;
  return {
    content: `${outcome}${usageNote}`,
    metadata: { topic: args.topic, blocks: blockLabels },
  };
}

// -- argument validation -----------------------------------------------------

/** Sums a per-block token field across every block consumed by the plans. */
function sumConsumedBlocks(
  plans: ResolvedPlan[],
  runtime: SessionRuntime,
  field: "summaryTokens" | "compressedTokens",
): number {
  let total = 0;
  for (const plan of plans) {
    for (const id of plan.consumedBlockIds) {
      total += Math.max(0, runtime.state.blocks[String(id)]?.[field] ?? 0);
    }
  }
  return total;
}

function validateArgs(input: unknown): PruneToolArgs {
  if (typeof input !== "object" || input === null) throw new Error("arguments must be an object");
  const raw = input as Record<string, unknown>;
  const topic =
    typeof raw.topic === "string" && raw.topic.trim().length > 0
      ? raw.topic.trim()
      : "Context pruning";
  const content = Array.isArray(raw.content) ? raw.content : [];
  if (content.length === 0) throw new Error("content must be a non-empty array of ranges");
  const entries: PruneRangeEntry[] = [];
  for (const item of content) {
    if (typeof item !== "object" || item === null)
      throw new Error("each range entry must be an object");
    const entry = item as Record<string, unknown>;
    const startId = typeof entry.startId === "string" ? entry.startId : "";
    const endId = typeof entry.endId === "string" ? entry.endId : "";
    const summary = typeof entry.summary === "string" ? entry.summary : "";
    if (!startId || !endId) throw new Error("each range needs string startId and endId");
    if (summary.trim().length === 0) throw new Error("each range needs a non-empty summary");
    entries.push({ startId, endId, summary });
  }
  return { topic, content: entries };
}

// -- range resolution --------------------------------------------------------

function resolvePlans(
  args: PruneToolArgs,
  index: TranscriptIndex,
  runtime: SessionRuntime,
): ResolvedPlan[] {
  const keyToIndex = new Map<string, number>();
  index.keys.forEach((key, i) => keyToIndex.set(key, i));
  const blocks = activeBlocks(runtime.state);
  const anchors = new Map(blocks.map((block) => [
    block.blockId, compressionAnchorIndex(block, keyToIndex, index.keys.length),
  ]));
  const hidden = new Set(blocks.flatMap((block) => block.coveredKeys));
  const visible: Array<{ key: string } | { block: CompressionBlock }> = [];
  for (const [i, key] of index.keys.entries()) {
    for (const block of blocks) {
      if (anchors.get(block.blockId) === i) visible.push({ block });
    }
    if (!hidden.has(key)) visible.push({ key });
  }
  for (const block of blocks) {
    if (anchors.get(block.blockId) === index.keys.length) visible.push({ block });
  }
  const keyToPosition = new Map<string, number>();
  const blockToPosition = new Map<number, number>();
  visible.forEach((entry, position) => {
    if ("key" in entry) keyToPosition.set(entry.key, position);
    else blockToPosition.set(entry.block.blockId, position);
  });

  const claimedKeys = new Set<string>();
  const claimedBlocks = new Set<number>();
  const plans: ResolvedPlan[] = [];

  for (const entry of args.content) {
    const startIndex = boundaryToIndex(entry.startId, keyToPosition, blockToPosition, runtime, "startId");
    const endIndex = boundaryToIndex(entry.endId, keyToPosition, blockToPosition, runtime, "endId");
    if (startIndex === undefined || endIndex === undefined) continue;
    if (startIndex > endIndex) {
      throw new Error(`startId ${entry.startId} appears after endId ${entry.endId}`);
    }

    const covered = new Set<string>();
    const consumedBlockIds: number[] = [];
    // Select the visible interval, never a block's hidden original span.
    for (let i = startIndex; i <= endIndex; i++) {
      const selected = visible[i]!;
      if ("block" in selected) {
        consumedBlockIds.push(selected.block.blockId);
        for (const key of selected.block.coveredKeys) covered.add(key);
        continue;
      }
      if (covered.has(selected.key)) continue;
      const rawIndex = keyToIndex.get(selected.key)!;
      let first = rawIndex;
      if (index.messages[first]?.role === "tool") {
        while (first > 0 && index.messages[first - 1]?.role === "tool") first--;
        if (index.messages[first - 1]?.role === "assistant") first--;
      }
      let last = rawIndex;
      while (index.messages[last + 1]?.role === "tool") last++;
      for (let j = first; j <= last; j++) covered.add(index.keys[j]!);
    }

    // Snapping a tool batch into a block consumes it whole, but its anchor alone never does.
    let changed = true;
    while (changed) {
      changed = false;
      for (const block of blocks) {
        if (consumedBlockIds.includes(block.blockId)) continue;
        if (!block.coveredKeys.some((key) => covered.has(key))) continue;
        consumedBlockIds.push(block.blockId);
        for (const key of block.coveredKeys) covered.add(key);
        changed = true;
      }
    }

    // Rebuild coveredKeys from the covered set (includes consumed block keys
    // that fall outside the original message index range).
    const finalCoveredKeys = [...covered]
      .filter((key) => keyToIndex.has(key))
      .sort((left, right) => (keyToIndex.get(left) ?? 0) - (keyToIndex.get(right) ?? 0));

    if (
      finalCoveredKeys.some((key) => claimedKeys.has(key)) ||
      consumedBlockIds.some((id) => claimedBlocks.has(id))
    ) {
      throw new Error(`ranges overlap: ${entry.startId}..${entry.endId} intersects another range`);
    }
    for (const key of finalCoveredKeys) claimedKeys.add(key);
    for (const id of consumedBlockIds) claimedBlocks.add(id);
    const last = visible[endIndex]!;
    let anchorKey: string;
    if ("block" in last) {
      anchorKey = last.block.anchorKey;
    } else {
      let rawEnd = keyToIndex.get(last.key)!;
      while (index.messages[rawEnd + 1]?.role === "tool") rawEnd++;
      anchorKey = index.keys[rawEnd + 1] ?? TAIL_ANCHOR;
    }

    const finalCoveredToolIds = index.toolOrder.filter(
      (callId) => index.tools.get(callId)?.hasResult && covered.has(index.tools.get(callId)!.key),
    );
    plans.push({
      entry,
      coveredKeys: finalCoveredKeys,
      coveredToolIds: finalCoveredToolIds,
      coveredTokens: estimateCoveredTokens(index, finalCoveredKeys),
      anchorKey,
      consumedBlockIds,
    });
  }

  if (plans.length === 0) {
    throw new Error("none of the provided IDs exist in the current context");
  }
  return plans;
}

function boundaryToIndex(
  id: string,
  keyToPosition: Map<string, number>,
  blockToPosition: Map<number, number>,
  runtime: SessionRuntime,
  field: string,
): number | undefined {
  const parsed = parseBoundaryChecked(id, field);
  if (parsed.kind === "message") {
    const refKey = runtime.refs.keyOf(parsed.ref);
    const idx = refKey !== undefined ? keyToPosition.get(refKey) : undefined;
    if (idx !== undefined) return idx;
    throw new Error(`${field} ${id} does not exist in the current context`);
  }
  const block = runtime.state.blocks[String(parsed.blockId)];
  if (!block) throw new Error(`${field} ${id} references an unknown compressed block`);
  if (!block.active) throw new Error(`${field} ${id} references an inactive compressed block`);
  const position = blockToPosition.get(parsed.blockId);
  if (position === undefined) throw new Error(`${field} ${id} references a block with no visible summary`);
  return position;
}

type ParsedBoundary = { kind: "message"; ref: string } | { kind: "block"; blockId: number };

function parseBoundaryChecked(id: string, field: string): ParsedBoundary {
  const messageIndex = parseMessageRef(id);
  if (messageIndex !== null)
    return { kind: "message", ref: `m${String(messageIndex).padStart(4, "0")}` };
  const blockId = parseBlockRef(id);
  if (blockId !== null) return { kind: "block", blockId };
  throw new Error(`${field} "${id}" is not a valid mNNNN or bN ID`);
}

// -- summary assembly --------------------------------------------------------

const BLOCK_PLACEHOLDER_REGEX = /\(\s*b(\d+)\s*\)/g;

/**
 * Expands `(bN)` placeholders with stored block summaries. Consumed blocks
 * whose placeholder is absent are intentionally DROPPED: their content leaves
 * the outbound transcript (it stays in persisted state, but inactive). This
 * is how the model prunes previously compressed sections whose work is no
 * longer relevant to the current task.
 */
export function expandPlaceholders(summary: string, state: SessionState): string {
  return summary.replace(BLOCK_PLACEHOLDER_REGEX, (_match, digits: string) => {
    const blockId = Number.parseInt(digits, 10);
    const block = state.blocks[String(blockId)];
    if (!block) throw new Error(`summary references unknown compressed block b${blockId}`);
    return stripBlockWrapper(block);
  });
}

/** Unwraps a stored block summary to its bare content for folding. */
export function stripBlockWrapper(block: CompressionBlock): string {
  return block.summary
    .replace(/^\[Compressed conversation section\]\n/, "")
    .replace(/<dcp-message-id>b\d+<\/dcp-message-id>\n?$/, "")
    .trim();
}

/**
 * Tokens a covered range reclaims - the figure behind both the zero-gain guard
 * and the savings the tool reports back to the model.
 *
 * The four explicit branches measure WHAT THE MODEL SEES, and must keep doing
 * so: a tool result is charged the indexed `outputText`, never the raw result
 * envelope, because the envelope is not what leaves the outbound transcript.
 *
 * Every other `ContentPart` variant carries no such string - `compaction`
 * (a provider checkpoint, billed as input on every following request), `media`
 * (paid for by geometry, not by encoded length) and `effort` (a marker) - so
 * they fall through to the SAME {@link measurePartChars} walk the context
 * estimate uses. Priced separately they read as zero: a range covering a large
 * checkpoint blob was reported as freeing nothing and could be refused as "not
 * worth compressing", while the model was told a smaller saving than it got.
 *
 * Cheap by construction: the walk reads field lengths, never the payload, so a
 * multi-megabyte `encrypted` blob costs one `.length`.
 */
function estimateCoveredTokens(index: TranscriptIndex, coveredKeys: string[]): number {
  const coveredSet = new Set(coveredKeys);
  let total = 0;
  for (let i = 0; i < index.messages.length; i++) {
    if (!coveredSet.has(index.keys[i]!)) continue;
    const message = index.messages[i]!;
    for (const part of message.content) {
      if (part.type === "text" || part.type === "reasoning") total += countTokens(part.text);
      else if (part.type === "tool-result")
        total += countTokens(index.tools.get(part.id)?.outputText ?? "");
      else if (part.type === "tool-call") total += countTokens(safeJson(part.input));
      else total += estimateTokens(measurePartChars(part));
    }
  }
  return total;
}

function safeJson(value: unknown): string {
  try {
    return JSON.stringify(value) ?? "";
  } catch {
    return "";
  }
}
